INSERT INTO solicitations (id, position, name, agency, opportunity_number, close, solicitation, award_ceiling, award_floor, total_program_funding, expected_awards, description) VALUES
('278447', 40, 'Computational Mathematics', 'U.S. National Science Foundation', 'PD-16-1271', 'Dec 01, 2026 12:00:00 AM EST', 'http://www.nsf.gov/funding/pgm_summ.jsp?pims_id=5390', 1200000, 1, 18000000, NULL, 'Supports mathematical research in areas where computation plays a central and essential role, emphasizing analysis, development, and implementation of theoretically justified and efficient algorithms. The combination of these elements resulting in innovative computational methods is a hallmark of the program. Proposals ranging from single investigator to interdisciplinary team projects that not only create and analyze new computational mathematics techniques but also implement them to model, study, and solve important application problems are strongly encouraged, as is providing opportunities for rigorous mathematical training of junior computational mathematicians through research involvement.'||char(10)||''||char(10)||''||char(10)||'Conferences'||char(10)||''||char(10)||''||char(10)||'Proposals to the Computational Mathematics Program for conferences or workshops must be submitted through the program solicitation "Conferences and Workshops in the Mathematical Sciences" (link below). Principal Investigators should carefully read the solicitation to obtain important information regarding the substance of proposals for conferences, workshops, and similar activities.'||char(10)||''||char(10)||''||char(10)||'Unless an exception from the program is granted, to facilitate timely notification of the availability of support, the following requirements are in effect:'||char(10)||''||char(10)||' '||char(10)||' Proposals for conferences, workshops, etc., to be held in the US must be submitted at least 6 months in advance of the conference start date; '||char(10)||' Proposals to support group travel to meetings outside the US must be submitted at least 8 months in advance of the meeting start date; '||char(10)||' Proposals for conferences, workshops, etc., whose budget request exceeds $50,000 must be submitted during the annual Computational Mathematics Program submission window. '||char(10)||' '||char(10)||''||char(10)||'Conference proposals to the Computational Mathematics Program whose submission dates do not conform with the requirements described above will be returned without review.'),
('320087', 43, 'Security and Preparedness', 'U.S. National Science Foundation', 'PD-19-118Y', NULL, 'http://www.nsf.gov/funding/pgm_summ.jsp?pims_id=505712', NULL, NULL, NULL, NULL, 'The Security and Preparedness (SAP) Programsupports basic scientific research that advances knowledge and understanding of issues broadly related to global and national security. Research proposals are evaluated on the criteria of intellectual merit and broader impacts; the proposed projects are expected to be theoretically motivated, conceptually precise, methodologically rigorous, and empirically oriented. Moreover, the Program supports research experiences for undergraduate students and infrastructural activities, including methodological innovations. The Program does not fund applied research. In addition, we encourage you to examine the websites for the National Science Foundation''sAccountable Institutions and Behavior(AIB), Law and Science (LS) programs, and Research Infrastructure in the Social and Behavioral Sciences (RISBS) programs.'),
('324369', 1, 'Foundational Research in Robotics', 'U.S. National Science Foundation', 'PD-20-144Y', NULL, 'http://www.nsf.gov/funding/pgm_summ.jsp?pims_id=505784', NULL, NULL, NULL, NULL, 'The Foundational Research in Robotics (FRR) program, jointly led by the CISE and ENG Directorates, supports research on robotic systems that exhibit significant levels of both computational capability and physical complexity. For the purposes of this program, a robot is defined as intelligence embodied in an engineered construct, with the ability to process information, sense, plan, and move within or substantially alter its working environment. Here intelligence includes a broad class of methods that enable a robot to solve problems or to make contextually appropriate decisions and act upon them. The program welcomes research that considers inextricably interwoven questions of intelligence, computation, and embodiment. Projects may also focus on a distinct aspect of intelligence, computation, or embodiment, as long as the proposed research is clearly justified in the context of a class of robots.'||char(10)||''||char(10)||''||char(10)||'The focus of the FRR program is on foundational advances in robotics. Robotics is a deeply interdisciplinary field, and proposals are encouraged across the full range of fundamental engineering and computer science research challenges arising in robotics. To be responsive to the FRR program, each proposal should clearly articulate the following three points:'||char(10)||''||char(10)||' '||char(10)||' The focus of the research project should be a robot or a class of robots, as defined above. [Is there a robot?] '||char(10)||' The goal of the project should be to endow a robot or a class of robots with new and useful capabilities or to significantly enhance existing capabilities. [Will a robot gain a new or significantly improved capability?] '||char(10)||' The intellectual contribution of the proposed work should address fundamental gaps in robotics. [Is robotics essential to the intellectual merit of the proposal?] '||char(10)||' '||char(10)||''||char(10)||'Meaningful experimental validation on a physical platform is encouraged.'||char(10)||''||char(10)||''||char(10)||'Projects that do not represent a direct fundamental contribution to the science of robotics or are better aligned with other existing programs at NSF should not be submitted to the FRR program.'||char(10)||''||char(10)||''||char(10)||'Potential investigators are strongly encouraged to discuss their projects with an FRR Program Officer before submission. Non-compliant proposals may be returned without review.'),
('324456', 15, 'Expeditions in Computing', 'U.S. National Science Foundation', '20-544', 'Mar 31, 2027 12:00:00 AM EDT', 'http://www.nsf.gov/publications/pub_summ.jsp?ods_key=nsf20544', NULL, 15000000, 60000000, 4, 'The far-reaching impact and rate of innovation in the computer and information science and engineering ﬁelds has been remarkable, generating economic prosperity and enhancing the quality of life for people throughout the world.'||char(10)||''||char(10)||''||char(10)||'More than a decade ago, the National Science Foundation’s (NSF) Directorate for Computer and Information Science and Engineering (CISE) established the Expeditions in Computing (Expeditions) program to build on past successes and provide the CISE research and education community with the opportunity to pursue ambitious, fundamental research agendas that promise to deﬁne the future of computing and information.'||char(10)||''||char(10)||''||char(10)||'In planning Expeditions projects, investigators are strongly encouraged to come together within or across departments or institutions to combine their creative talents in the identiﬁcation of compelling, transformative research agendas that look ahead by at least a decade and promise disruptive innovations in computer and information science and engineering for many years to come.'||char(10)||''||char(10)||''||char(10)||'Now funded at levels up to $15,000,000 for seven years, Expeditions projects represent some of the largest single investments currently made by the CISE directorate. Together with the Science and Technology Centers and the National Artificial Intelligence Research Institutes that CISE supports, Expeditions projects form the centerpiece of the directorate''s center-scale award portfolio. With awards funded at levels that promote the formation of large research teams, CISE recognizes that concurrent research advances in multiple ﬁelds or sub-ﬁelds are often necessary to stimulate deep and enduring outcomes. The awards made in this program will complement research areas supported by other CISE programs, which target particular computer and information science and engineering ﬁelds.'||char(10)||''||char(10)||''||char(10)||'Additionally, CISE offers Innovation Transition (InTrans) awards for teams nearing the end of their Expeditions as well as Secure and Trustworthy Cyberspace (SaTC) and Cyber-Physical Systems (CPS) Frontier projects. The goal of InTransis to continue the long-term vision and objectives of CISE’s center-scale projects. Through InTrans awards, CISE will provide limited funds to match industry support.'),
('339594', 23, 'Faculty Early Career Development Program', 'U.S. National Science Foundation', '22-586', 'Jul 28, 2027 12:00:00 AM EDT', 'http://www.nsf.gov/publications/pub_summ.jsp?ods_key=nsf22586', NULL, 400000, 250000000, NULL, 'CAREER:The Faculty Early Career Development (CAREER) Program is a Foundation-wide activity that offers the National Science Foundation''s most prestigious awards in support of early-career faculty who have the potential to serve as academic role models in research and education and to lead advances in the mission of their department or organization. Activities pursued by early-career faculty should build a firm foundation for a lifetime of leadership in integrating education and research. NSF encourages submission of CAREER proposals from early-career faculty at all CAREER-eligible organizations .'||char(10)||''||char(10)||''||char(10)||'PECASE:Each year NSF selects nominees for the Presidential Early Career Awards for Scientists and Engineers (PECASE) from among the most meritorious recent CAREER awardees.Selection for this award is based on twoimportant criteria:The criteria are 1) performance of innovative research at the frontiers of science, engineering, and technology that is relevant to the mission of the sponsoring organization or agency; and 2) community service demonstrated through scientific leadership, education or community outreach.These awards foster innovative developments in science and technology, increase awareness of careers in science and engineering, give recognition to the scientific missions of the participating agencies, enhance connections between fundamental research and national goals, and highlight the importance of science and technology for the Nation’s future. Individuals cannot apply for PECASE. These awards are initiated by the participating federal agencies. At NSF, up to twenty-six nominees for this award are selected each year from among the PECASE-eligible CAREER awardees most likely to become the leaders of academic research and education in the twenty-first century. The White House Office of Science and Technology Policy makes the final selection and announcement of the awardees.'),
('342475', 13, 'NSF Dynamic Language Infrastructure - NEH Documenting Endangered Languages', 'U.S. National Science Foundation', '22-615', 'Sep 15, 2026 12:00:00 AM EDT', 'http://www.nsf.gov/publications/pub_summ.jsp?ods_key=nsf22615', NULL, NULL, 4800000, 25, 'This funding partnership between the National Science Foundation (NSF) and the National Endowment for the Humanities (NEH) supports projects to develop and advance knowledge concerning dynamic language infrastructure in the context of endangered human languages — languages that are both understudied and at risk of falling out of use. Made urgent by the imminent loss of roughly half of the approximately 7,000 currently used languages, this effort aims to exploit advances in human-language technology to build computational infrastructure for endangered language research. The program supports projects that contribute to data management and archiving, and to the development of the next generation of researchers. Funding can support fieldwork and other activities relevant to the digital recording, documentation and analysis, and archiving of endangered language data, including the preparation of lexicons, grammars, text samples, and databases. Funding is available in the form of one- to three-year senior research grants and conference proposals. Fellowship support is available through a separate funding opportunity administered by NEH .'||char(10)||''||char(10)||''||char(10)||'Note: a conference proposal should generally be submitted at least a year in advance of the scheduled date of the conference. For additional information about creating and submitting conference proposals, please refer to PAPPG Chapter II. E.9.'),
('344608', 12, 'Training-based Workforce Development for Advanced Cyberinfrastructure (CyberTraining)', 'U.S. National Science Foundation', '23-520', 'Jan 21, 2027 12:00:00 AM EST', 'http://www.nsf.gov/publications/pub_summ.jsp?ods_key=nsf23520', 1000000, NULL, 9300000, NULL, 'This program seeks to prepare, nurture, and grow the national scientific research workforce for creating, utilizing, and supporting advanced cyberinfrastructure (CI) to enable and potentially transform fundamental science and engineering (S&E) research and education and contribute to the Nation''s overall economic competitiveness and security. The goals of this solicitation are to (i) ensure broad adoption of CI tools, methods, and resources by the research community in order to catalyze major research advances and to enhance researchers’ abilities to lead the development of new CI, and (ii) integrate core literacy and discipline-appropriate advanced skills in advanced CI as well as computational and data-driven methods for advancing fundamental research, into the Nation’s undergraduate and graduate educational curriculum/instructional materials. Proposals responding to this solicitation may target one or both solicitation goals. For the purpose of this solicitation, advanced CI is broadly defined as the set of resources, tools, methods, and services for advanced computation, large-scale data handling and analytics, and networking and security for large-scale systems that collectively enable potentially transformative fundamental S&E research and education.'||char(10)||''||char(10)||''||char(10)||'This solicitation calls for innovative, scalable training, education, and curriculum/instructional materials—targeting one or more of the solicitation goals—to address emerging needs and unresolved bottlenecks in the S&E research workforce development, from the postsecondary level to active researchers to CI professionals. The funded activities, spanning targeted, multidisciplinary communities, should lead to transformative changes in the state of research workforce preparedness for advanced CI-enabled research in the short- and long-term. This solicitation also seeks to broaden CI access and adoption by (i) increasing the adoption of advanced CI and computational and data-driven methods to a broader range of S&E disciplines and institutions and (ii) effectively utilizing individual capabilities. Proposals from, and in partnership with, the aforementioned communities are especially encouraged.'||char(10)||''||char(10)||''||char(10)||'There are two project classes as defined below:'||char(10)||''||char(10)||' '||char(10)||' Pilot Projects: up to $300,000 total budget with durations up to two years; and '||char(10)||' Implementation Projects: Small (with total budgets of up to $500,000) or Medium (with total budgets of up to $1,000,000) for durations of up to four years. '||char(10)||' '||char(10)||''||char(10)||'Section II. Program Description provides a more complete description of the project classes. Section V.A. Proposal Preparation Instructions describes the proposal elements required for the various project classes in order to address the suitable set of solicitation-specific review criteria.'||char(10)||''||char(10)||''||char(10)||'The CyberTraining program is led by the Office of Advanced Cyberinfrastructure (OAC) in the Directorate for Computer and Information Science and Engineering (CISE) and has participation from other NSF directorates/divisions, as described in Section II. Program Description, Programmatic Areas of Interest. Not all directorates/divisions are participating at the same level, and some have specific research and education priorities. The appropriate contact for the CyberTraining program in any directorate/division is the Cognizant Program Officer (PO) for the respective directorate/division/office/program listed below.'||char(10)||''||char(10)||''||char(10)||'All projects are expected to clearly articulate how they will address important community needs and provide resources that will be widely available to and usable by the research community.Prospective principal investigators (PIs) are strongly encouraged to contact the Cognizant Program Officers in CISE/OAC and in the participating directorate/division relevant to the proposal to ascertain whether the focus and budget of their proposed activities are appropriate for this solicitation. Such consultations should be completed at least one month in advance of the submission deadline. PIs should include the names of the Cognizant Program Officers consulted in a Single Copy Document as described in Section V.A. Proposal Preparation Instructions. The intent of the CyberTraining program is to encourage collaboration between CI and S&E domain disciplines. (For this purpose, units of CISE other than OAC are considered domain disciplines.) To ensure relevance to community needs and to facilitate adoption, those proposals of interest to one or more domain divisions must include at least one PI/co-PI with expertise relevant to the targeted research discipline. All proposals shall include at least one PI/co-PI with expertise relevant to OAC.'||char(10)||''||char(10)||''||char(10)||'Prospective PIs contemplating submissions that primarily target communities relevant to directorates/divisions that are not participating in this solicitation are directed to instead explore the education and workforce development programs of the respective directorates/divisions.'),
('344610', 17, 'Major Research Instrumentation Program', 'U.S. National Science Foundation', '23-519', 'Nov 16, 2026 12:00:00 AM EST', 'http://www.nsf.gov/publications/pub_summ.jsp?ods_key=nsf23519', 4000000, 100000, 75000000, NULL, 'The Major Research Instrumentation (MRI) Program ( MRI Program Website) serves to increase access to multi-user scientific and engineering instrumentation for research and research training in our Nation''s institutions of higher education and not-for-profit scientific/engineering research organizations. An MRI award supports the acquisition of a multi-user research instrument that is commercially available through direct purchase from a vendor, or for the personnel costs and equipment that are required for the development of an instrument with new capabilities, thereby advancing instrumentation capabilities and enhancing expertise for instrument design and fabrication at academic institutions. MRI instruments are, in general, too costly and/or not appropriate for support through other NSF programs.'||char(10)||''||char(10)||''||char(10)||'MRI provides support to acquire critical research instrumentation without which advances in fundamental science and engineering research may not otherwise occur. MRI also provides support to obtain next-generation research instruments by developing instruments with new capabilities that open new opportunities to advance the frontiers in science and engineering research. Additionally, an MRI award is expected to enhance research training of students who will become the next generation of instrument users, designers and builders.'||char(10)||''||char(10)||''||char(10)||'An MRI proposal may request from NSF up to $4 million for either acquisition or development of a research instrument. Each performing organization may submit in revised "Tracks" as defined below, with no more than two (2) submissions in Track 1 and no more than one (1) submission in Track 2. For the newly defined Track 3, no more than one (1) submission per competition is permitted. As a result, it is now possible for an institution to submit up to four MRI proposals within the Track limits as described above. '||char(10)||''||char(10)||' '||char(10)||' Track 1: Track 1 MRI proposals are those that request funds from NSF greater than $100,000 [1] and less than $1,400,000. '||char(10)||' Track 2: Track 2 MRI proposals are those that request funds from NSF greater than or equal to $1,400,000 up to and including $4,000,000. '||char(10)||' Track 3: Track 3 MRI proposals are those that request funds from NSF greater than or equal to $100,000 [1] and less than or equal to $4,000,000 that include the purchase, installation, operation, and maintenance of equipment and instrumentation to conserve or reduce the consumption of helium. Institutions may submit no more than one Track 3 proposal. Submission of a Track 3 proposal does not impact limits that apply for Track 1 and Track 2 proposals. '||char(10)||' '||char(10)||''||char(10)||'Cost sharing requirements for new awards in the MRI Program are waived for a period of 5 years beginning with the FY 2023 MRI competition. Institutional submission limits for Track 1, Track 2 and Track 3 proposals remain.'||char(10)||''||char(10)||''||char(10)||'The MRI Program especially seeks broad representation of groups, institutions, and geographic regions that are underrepresented in STEM disciplines. Proposals from women, underrepresented minorities, persons with disabilities and early-career PIs are encouraged, as are proposals that benefit early-career researchers and proposals with PIs from geographically underserved regions, including EPSCoR jurisdictions. Additionally, proposals are encouraged from under-resourced institutions, including from emerging research institutions, where MRI can significantly build capacity for research.'||char(10)||''||char(10)||''||char(10)||'___________________________'||char(10)||''||char(10)||''||char(10)||' [1] Track 1 proposals requesting funds from NSF less than $100,000 will be accepted only from: a) eligible performing organizations requesting instrumentation supporting research in the disciplines of mathematics or social, behavioral and economic sciences; or b) non-Ph.D.-granting institutions of higher education requesting instrumentation supporting research in any NSF-supported disciplines.'),
('346204', 34, 'Communications, Circuits, and Sensing-Systems', 'National Science Foundation', 'PD-18-7564', NULL, 'http://www.nsf.gov/funding/pgm_summ.jsp?pims_id=505248', NULL, NULL, NULL, NULL, 'The Communications, Circuits, and Sensing-Systems (CCSS) Program supports innovative research in circuit and system hardware and signal processing techniques. CCSS also supports system and network architectures for communications and sensing to enable the next-generation cyber-physical systems (CPS) that leverage computation, communication, and sensing integrated with physical domains. CCSS invests in micro- and nano-electromechanical systems (MEMS/NEMS), physical, chemical, and biological sensing systems, neurotechnologies, and communication & sensing circuits and systems. The goal is to create new complex and hybrid systems ranging from nano- to macro-scale with innovative engineering principles and solutions for a variety of applications including but not limited to healthcare, medicine, environmental and biological monitoring, communications, disaster mitigation, homeland security, intelligent transportation, manufacturing, energy, and smart buildings. CCSS encourages research proposals based on emerging technologies and applications for communications and sensing such as high-speed communications of terabits per second and beyond, sensing and imaging covering microwave to terahertz frequencies, personalized health monitoring and assistance, secured wireless connectivity and sensing for the Internet of Things, and dynamic-data-enabled autonomous systems through real-time sensing and learning.'||char(10)||''||char(13)||''||char(10)||''||char(10)||'Areas managed by CCSS Program Directors (please contact Program Directors listed in the CCSS staff directory for areas of interest):'||char(10)||''||char(13)||''||char(10)||''||char(10)||'RF Circuits and Antennas for Communications and Sensing'||char(10)||''||char(13)||''||char(10)||' '||char(13)||''||char(10)||' RF Communications and Sensing Technologies from kHz to THz '||char(13)||''||char(10)||' Antennas and Wave Propagation for Communications and Sensing '||char(13)||''||char(10)||' Circuits and Systems for Secured Communications and Sensing '||char(13)||''||char(10)||' Trusted Microelectronic Circuits '||char(13)||''||char(10)||' RF Biomedical Applications and Remote Sensing '||char(13)||''||char(10)||' Bio-mimetic Circuits and Systems '||char(13)||''||char(10)||' Dynamic-data-enabled Reconfigurable RF Subsystems through Sensing and Machine Learning '||char(13)||''||char(10)||' Wireless Energy Transfer and RF Energy Harvesting '||char(13)||''||char(10)||' '||char(13)||''||char(10)||''||char(10)||'Communication Systems and Signal Processing'||char(10)||''||char(13)||''||char(10)||' '||char(13)||''||char(10)||' Wireless, Optical, and Hybrid Communications and Networking '||char(13)||''||char(10)||' Full-duplex, massive MIMO, mm-Wave, and THz communications '||char(13)||''||char(10)||' Spectrum Access and Sharing '||char(13)||''||char(10)||' Integrated Sensing, Communication, and Computational Systems '||char(13)||''||char(10)||' Signal Processing, image processing, and Compressive Sampling '||char(13)||''||char(10)||' Cyber Physical Systems and Hardware-controlled Secured Communications '||char(13)||''||char(10)||' Dynamic-data-enabled Communication Systems through Sensing and Machine Learning '||char(13)||''||char(10)||' Quantum Communication Systems '||char(13)||''||char(10)||' '||char(13)||''||char(10)||''||char(10)||'Dynamic Bio-Sensing Systems'||char(10)||''||char(13)||''||char(10)||' '||char(13)||''||char(10)||' Micro, Nano, and Bio Systems (MEMS/NEMS) '||char(13)||''||char(10)||' Chemical, Biological, and Physical Diagnostics '||char(13)||''||char(10)||' Sensors, Actuators, and Electronic Interfaces '||char(13)||''||char(10)||' Ultra-Low Power Wearable and Implantable Sensing Systems '||char(13)||''||char(10)||' Dynamic-data-enabled Reconfigurable Sensing Systems '||char(13)||''||char(10)||' Personalized Health Monitoring Systems through Sensing and Machine Learning '||char(13)||''||char(10)||' Neuroengineering and Brain-Inspired Concepts and Designs'),
('348258', 33, 'Energy, Power, Control, and Networks', 'National Science Foundation', 'PD-18-7607', NULL, 'http://www.nsf.gov/funding/pgm_summ.jsp?pims_id=505249', NULL, NULL, NULL, NULL, 'The Energy, Power, Control, andNetworks (EPCN) Program supports innovative research in modeling, optimization, learning, adaptation, and control of networked multi-agent systems, higher-level decision making, and dynamic resource allocation, as well as risk management in the presence of uncertainty, sub-system failures, and stochastic disturbances. EPCN also invests in novel machine learning algorithms and analysis, adaptive dynamic programming, brain-like networked architectures performing real-time learning, and neuromorphic engineering. EPCN’s goal is to encourage research on emerging technologies and applications including energy, transportation, robotics, and biomedical devices & systems. EPCN also emphasizes electric power systems, including generation, transmission, storage, and integration of renewable energy sources into the grid; power electronics and drives; battery management systems; hybrid and electric vehicles; and understanding of the interplay of power systems with associated regulatory & economic structures and with consumer behavior.'||char(10)||''||char(13)||''||char(10)||''||char(10)||'Areas managed by Program Directors (please contact Program Directors listed in the EPCN staff directory for areas of interest):'||char(10)||''||char(13)||''||char(10)||''||char(10)||'Control Systems'||char(10)||''||char(13)||''||char(10)||' '||char(13)||''||char(10)||' Distributed Control and Optimization '||char(13)||''||char(10)||' Networked Multi-Agent Systems '||char(13)||''||char(10)||' Stochastic, Hybrid, Nonlinear Systems '||char(13)||''||char(10)||' Dynamic Data-Enabled Learning, Decision and Control '||char(13)||''||char(10)||' Cyber-Physical Control Systems '||char(13)||''||char(10)||' Applications (Biomedical, Transportation, Robotics) '||char(13)||''||char(10)||' '||char(13)||''||char(10)||''||char(10)||'Energy and Power Systems'||char(10)||''||char(13)||''||char(10)||' '||char(13)||''||char(10)||' Solar, Wind, and Storage Devices Integration with the Grid '||char(13)||''||char(10)||' Monitoring, Protection and Resilient Operation of Grid '||char(13)||''||char(10)||' Power Grid Cybersecurity '||char(13)||''||char(10)||' Market design, Consumer Behavior, Regulatory Policy '||char(13)||''||char(10)||' Microgrids '||char(13)||''||char(10)||' Energy Efficient Buildings and Communities '||char(13)||''||char(10)||' '||char(13)||''||char(10)||''||char(10)||'Power Electronics Systems'||char(10)||''||char(13)||''||char(10)||' '||char(13)||''||char(10)||' Advanced Power Electronics and Electric Machines '||char(13)||''||char(10)||' Electric and Hybrid Electric Vehicles '||char(13)||''||char(10)||' Energy Harvesting, Storage Devices and Systems '||char(13)||''||char(10)||' Innovative Grid-tied Power Electronic Converters '||char(13)||''||char(10)||' '||char(13)||''||char(10)||''||char(10)||'Learning and Adaptive Systems '||char(10)||''||char(13)||''||char(10)||' '||char(13)||''||char(10)||' Neural Networks '||char(13)||''||char(10)||' Neuromorphic Engineering Systems '||char(13)||''||char(10)||' Data analytics and Intelligent Systems '||char(13)||''||char(10)||' Machine Learning Algorithms, Analysis and Applications'),
('348599', 4, 'Historically Black Colleges and Universities - Excellence in Research', 'U.S. National Science Foundation', '23-598', 'Oct 20, 2026 12:00:00 AM EDT', 'http://www.nsf.gov/publications/pub_summ.jsp?ods_key=nsf23598', NULL, NULL, 28000000, 35, 'The Historically Black Colleges and Universities - Excellence in Research (HBCU-EiR) program was established in response to direction provided in the Senate Commerce and Justice, Science and Related Agencies Appropriations Subcommittee Report (Senate Report 115-139), and is built on prior and continuing efforts by the National Science Foundation (NSF) to strengthen research capacity at Historically Black Colleges and Universities (HBCUs). This report provided guidance to NSF to establish the HBCU Excellence in Research program "to provide opportunities for both public and private HBCUs, particularly for those who have not been successful in larger NSF Research & Related Activities competitions, in order to stimulate sustainable improvement in their research and development capacity" ( https://congress.gov/congressional-report/115th-congress/senate-report/139/1 ).'||char(10)||''||char(10)||''||char(10)||'EiR supports such capacity building by funding research projects aligned with NSF''s research programs. The program aims to establish stronger connections between researchers at HBCUs and NSF''s research programs.'),
('348985', 29, 'Research Experiences for Undergraduates (REU)', 'U.S. National Science Foundation', '23-601', 'Aug 18, 2027 12:00:00 AM EDT', 'http://www.nsf.gov/publications/pub_summ.jsp?ods_key=nsf23601', 500000, 5000, 84800000, 1350, 'The Research Experiences for Undergraduates (REU) program supports active research participation by undergraduate students in any of the areas of research funded by the National Science Foundation. REU projects involve students in meaningful ways in ongoing research programs or in research projects specifically designed for the REU program. This solicitation features two mechanisms for supporting student research: '||char(10)||' '||char(10)||' REU Sites are based on independent proposals to initiate and conduct projects that engage a number of students in research. REU Sites may be based in a single discipline or academic department or may offer interdisciplinary or multi-department research opportunities with a coherent intellectual theme. '||char(10)||' REU Supplements may be included as a component of proposals for new or renewal NSF grants or cooperative agreements or may be requested for ongoing NSF-funded research projects. '||char(10)||' '||char(10)||' REU projects with an international dimension are welcome. '||char(10)||' Undergraduate student participants in either REU Sites or REU Supplements must be U.S. citizens, U.S. nationals, or U.S. permanent residents. '||char(10)||' Students do not apply to NSF to participate in REU activities, and NSF does not select students for the opportunities. Investigators who receive REU awards establish their own process for receiving and reviewing applications and selecting students, and students follow the instructions provided by each REU Site or REU Supplement to apply. (In some cases, investigators pre-select students for REU Supplements.) To identify appropriate REU Sites, students should consult the directory of active REU Sites on the Web at https://www.nsf.gov/crssprgm/reu/reu_search.cfm .'),
('350802', 25, 'Research Experiences for Teachers (RET) in Engineering and Computer Science', 'U.S. National Science Foundation', '24-503', 'Oct 14, 2026 12:00:00 AM EDT', 'http://www.nsf.gov/publications/pub_summ.jsp?ods_key=nsf24503', NULL, 600000, 5800000, NULL, 'The Research Experiences for Teachers (RET) in Engineering and Computer Science program supports authentic summer research experiences for K-14 educators to foster long-term collaborations between universities, community colleges, school districts, and industry partners. With this solicitation, the Directorates for Engineering (ENG) and Computer and Information Science and Engineering (CISE) focus on a reciprocal exchange of expertise between K-14 educators and research faculty and (when applicable) industry mentors. K-14 educators will enhance their scientific disciplinary knowledge in engineering or computer science and translate their research experiences into classroom activities and curricula to broaden their students’ awareness of and participation in computing and engineering pathways. At the same time, the hosting research faculty will deepen their understanding of classroom practices, current curricula, pedagogy, and K-14 educational environments.'),
('351889', 5, 'GROWING CONVERGENCE RESEARCH', 'U.S. National Science Foundation', '24-527', 'Feb 08, 2027 12:00:00 AM EST', 'http://www.nsf.gov/publications/pub_summ.jsp?ods_key=nsf24527', 3600000, 1200000, 16000000, 10, 'Convergence research is a means for solving vexing research problems, in particular, complex problems focusing on societal needs or deep scientific challenges. It entails integrating knowledge, methods, and expertise from different disciplines and developing novel paradigms that catalyze scientific discovery and innovation.'||char(10)||''||char(10)||''||char(10)||'GCR identifies Convergence Research as having two primary characteristics:'||char(10)||''||char(10)||' '||char(10)||' Research driven by a specific and compelling problem.Convergence research is generally inspired by the need to address a specific challenge or opportunity, whether it arises from deep scientific questions or pressing societal needs. '||char(10)||' Deep integration across disciplines.As experts from different disciplines pursue common research challenges, their knowledge, theories, methods, data, research communities andlanguages become increasingly intermingled or integrated. New frameworks, paradigms or even disciplines can form sustained interactions across multiple communities. '||char(10)||' '||char(10)||''||char(10)||'A distinct characteristic of convergence research, in contrast to other forms of multidisciplinary research, is that from the inception, the convergence paradigmintentionallybrings together intellectually diverse researchers and stakeholders to frame the research questions, adopt common frameworks for addressing them, and create and implement innovative scientific approaches for their solution. This includes, when appropriate, developing new integrated theories, methods, research tools, and ways of communicating across disciplines and sectors.Research teams practicing convergence aim to develop sustainable collaborations that may not only create solutions to the specific problem studied, but also develop novel ways of investigating related research questions and open new research vistas.'||char(10)||''||char(10)||''||char(10)||'This GCR solicitation targets multidisciplinary teams who are embracing convergence research as a means of developing highly innovative solutions to complex research problems. GCR proposals are expected to be bold and address scientific or technical challenges and bottlenecks which if resolved have the potential to transform scientific understanding and solve vexing problems. Successful GCR projects are anticipated to lead to paradigm shifting approaches within disciplines, establishment of new scientific communities, or development of transformative technologies that have the potential for broad scientific or societal impact.'||char(10)||''||char(10)||''||char(10)||'The aim of GCR is to cultivate and grow the earliest foundations of convergent approaches for addressing a specific and compelling problem. As such, proposals submitted to this solicitation are expected to explore novel avenues not previously investigated that are at the forefront of advancing science through deep integration. Proposers must make a convincing case that the research to be conducted is within NSF’s purview, integrates across NSF directorate or division boundaries, and is currently not supported by other NSF programs or solicitations.'||char(10)||''||char(10)||''||char(10)||'The proposers must outline a five-year research plan delineated in two phases, Phase I: years 1-2, and Phase II: years 3-5.The total budget for Phase I may not exceed $1,200,000, and the total for Phase II may not exceed $2,400,000. Successful proposals will be funded initially for two years. Each team’s progress will be evaluated at a reverse site visit near the end of year 2; this will involve preparing a progress report and making a team presentation to a panel of reviewers/site visitors. Only teams that show exceptional progress according to the merit review and solicitation specific criteria during the first two years and that articulate plans for furthering advancements at the forefront of convergence research will be eligible for additional funding for up to three years pending availability of funds.'),
('351923', 20, 'EPSCoR Research Infrastructure Improvement (RII): EPSCoR Research Fellows', 'U.S. National Science Foundation', '24-528', 'Apr 13, 2027 12:00:00 AM EDT', 'http://www.nsf.gov/publications/pub_summ.jsp?ods_key=nsf24528', NULL, NULL, 15000000, NULL, 'The Established Program to Stimulate Competitive Research is designed to fulfill the mandate of the National Science Foundation (NSF) to promote scientific progress nationwide. NSF EPSCoR facilitates the establishment of partnerships among academic institutions, government, industry, and non-profit sectors that are designed to promote sustainable improvements in a jurisdiction''s research infrastructure, Research and Development (R&D) capacity, and R&D competitiveness of EPSCoR-eligible jurisdictions (i.e., states, territories, and commonwealths). Eligibility to participate in the EPSCoR funding opportunities, including the EPSCoR RII: EPSCoR Research Fellows program, is described on the NSF EPSCoR website .'||char(10)||''||char(10)||''||char(10)||'EPSCoR RII: EPSCoR Research Fellows directly aligns with the NSF EPSCoR strategic goal of establishing sustainable Science, Technology, Engineering, and Mathematics (STEM) professional development pathways that advance workforce development and effects engagement in STEM at national and global levels. EPSCoR RII: EPSCoR Research Fellows provides awards to build researchcapacityin institutions and transform the career trajectories of investigators and further develop their individual research potential through collaborations with investigators from the nation’s premier private, governmental, or academic research institutions and/or centers. The fellowship provides opportunities to establish strong collaborations through extended or periodic collaborative visits to a selected host site.Through collaborative research activities with the host site, Fellows will be able to learn new techniques, develop new collaborations, advance existing partnerships, benefit from access to unique equipment and facilities, and/or shift their research toward potentially transformative new directions. The experiences gained through the fellowships are intended to have lasting impacts that will enhance the Fellows’ research trajectories well beyond the award period. The benefits to the Fellows are also expected to improve the research capacity of their institutions and jurisdictions more broadly.'||char(10)||''||char(10)||''||char(10)||'EPSCoR Research Infrastructure Improvement (RII): EPSCoR Research Fellows offers the following two tracks:'||char(10)||''||char(10)||''||char(10)||'1)EPSCoR Research Fellows: NSF; and'||char(10)||''||char(10)||''||char(10)||'2) EPSCoR Research Fellows: @NASA '||char(10)||''||char(10)||''||char(10)||'While the two tracks have similar goals, EPSCoR Research Fellows: NSF is open to a broad community and EPSCoR Research Fellows: @NASA supports faculty from eligible institutions (See Section"IV. Eligibility Information" for more details) to collaborate with researchers at the National Aeronautics and Space Administration (NASA) research centers. PIs who are eligible for both tracks may apply for only one track per competition cycle.'||char(10)||''||char(10)||''||char(10)||'Proposals from both tracks are submitted to and merit reviewed by NSF. Awards in the EPSCoR Research Fellows: @NASA track are referred to NASA EPSCoR for distribution of additional NASA funds and other needed NASA coordination required for the award.'||char(10)||''||char(10)||''||char(10)||'In both tracks, the EPSCoR RII: EPSCoR Research Fellows program provides opportunities for the participation of one trainee, who must be an undergraduate or graduate student enrolled full-time in an accredited degree program, or a postdoctoral researcher from an EPSCoR jurisdiction. Staff members, such as technicians or lab assistants could be considered as trainees when properly justified.'),
('352339', 0, 'Established Program to Stimulate Competitive Research (EPSCoR): Workshop Opportunities', 'U.S. National Science Foundation', '24-540', NULL, 'http://www.nsf.gov/publications/pub_summ.jsp?ods_key=nsf24540', 200000, NULL, 1500000, 20, 'The Established Program to Stimulate Competitive Research (EPSCoR) is designed to fulfill the mandate of the National Science Foundation (NSF) to promote scientific progress nationwide. NSF EPSCoR facilitates the establishment of partnerships among academic institutions, government, industry, and non-profit sectors that are designed to promote sustainable improvements in an EPSCoR-eligible jurisdiction’s research infrastructure, Research and Development (R&D) capacity, and R&D competitiveness. Eligibility to participate in NSF EPSCoR funding opportunities, including the EPSCoR Workshop Opportunities program, is described on the EPSCoR website (see criteria for eligibility link ).'||char(10)||''||char(10)||''||char(10)||'EPSCoR welcomes proposals for workshops only from institutions within EPSCoR-eligible jurisdictions (i.e. states, territories, commonwealths). These workshops must focus on innovative ways to address multi-jurisdictional efforts on themes of regional or national importance with relevance to the goals and mission of NSF and EPSCoR .'),
('353475', 2, 'Cyberinfrastructure for Public Access and Open Science', 'U.S. National Science Foundation', 'PD-24-7414', NULL, 'http://www.nsf.gov/funding/pgm_summ.jsp?pims_id=506307', 600000, 50000, 600000, 10, 'The Cyberinfrastructure for Public Access and Open Science (CI PAOS) program within the Office of Advanced Cyberinfrastructure (OAC) aims to catalyze new and transformative socio-technical partnerships supporting research data infrastructure ecosystems across d omains through early-stage collaborative activities between cyberinfrastructure researchers, scie ntists , research computing experts, data management experts , research labs , university libraries , and other communities of practice. '||char(10)||''||char(10)||' '||char(10)||' '||char(10)||' The CI PAOS program supports the NSF Public Access Initiative by encouraging innovation across the CI ecosystem t o address accessibility, discoverability, reliability, reproducibility, sustainability, and utility of data products in alignment with NSF and national goals for public access and open science [ See: NSF Public Access Initiative , Office of Science and Technology Policy Memorandum on Ensuring Free, Immediate, and equitable Access to Federally funded Research , and Desirable Characteristics of Data Repositories for Federally Funded Research ] . CI PAOS builds on previous investments including those through Dear Colleague Letters NSF 19-069 , NSF 20 -068 , NSF 23-018 , and the FAIROS R esearch C oordination N etworks ( RCN ) p rogram solicitation ( NSF 22-553 ) . '||char(10)||''||char(10)||' '||char(10)||' '||char(10)||' NSF accepts proposals pursuant to this Program Description year-round. From time to time , NSF may also issue Dear Colleague Letters to encourage proposals on special thema tic interests and opportunities related to this progra m . '||char(10)||''||char(10)||' '||char(10)||' GUIDANCE TO POTENTIAL PROPOSERS '||char(10)||''||char(10)||' '||char(10)||' '||char(10)||' A primary feature of successful CI PAOS projects is a robust, synergistic collaborative team comprising skills from across communities of science/engineering, research data science, and information science discipline(s) and expertise in leveraging connections between cyberinfrastructure researchers and providers and data specialists . Leveraging international collaboration to build shared norms and address c hallenges related to developing and implementing PAOS policies and practices is encouraged . Research and education in science and engineering benefit immensely from international cooperation. P roposals with an international component are also welcome [See: International Collaborations Opportunities at NSF ] . Proposers must target one or more of th e following themes/pathways: Competency Building, Capability Building, and /or Community Building. '||char(10)||''||char(10)||' '||char(10)||' '||char(10)||' Competency Building '||char(10)||''||char(10)||' '||char(10)||' '||char(10)||' Open s cience /engineering-driven collaboration . A socio -technical collaborative approach in addressing disciplinary , interdisciplinary , domestic, and international data lifecycle challenges is critical to informing and guiding the development of principles, requirements , and standards of a CI ecosystem that fosters pipelines to good data management and pathways to access. Propos al s should clearly describe the goals, challenges, and rationale for the proposed data science and engineering project and include an explanation of the potential for transformative research and broader impacts on the open science ecosystem [ See: U.S. NSF Broader Impacts ] . Successful proposals will also clearly identify utilization science scenarios and use cases . '||char(10)||''||char(10)||' '||char(10)||' '||char(10)||' C apability Building '||char(10)||''||char(10)||' '||char(10)||' '||char(10)||' Exploratory and pilot activities. <span class="TextRun SCXW92189242 BCX4" lang="EN-US" xml:lang="EN-US" d'),
('353936', 3, 'Mathematical Foundations of Artificial Intelligence', 'U.S. National Science Foundation', '24-569', 'Oct 09, 2026 12:00:00 AM EDT', 'http://www.nsf.gov/publications/pub_summ.jsp?ods_key=nsf24569', 1500000, 500000, 8500000, NULL, 'Machine Learning and Artificial Intelligence (AI) are enabling extraordinary scientific breakthroughs in fields ranging from protein folding, natural language processing, drug synthesis, and recommender systems to the discovery of novel engineering materials and products. These achievements lie at the confluence of mathematics, statistics, engineering and computer science, yet a clear explanation of the remarkable power and also the limitations of such AI systems has eluded scientists from all disciplines. Critical foundational gaps remain that, if not properly addressed, will soon limit advances in machine learning, curbing progress in artificial intelligence. It appears increasingly unlikely that these critical gaps can be surmounted with increased computational power and experimentation alone. Deeper mathematical understanding is essential to ensuring that AI can be harnessed to meet the future needs of society and enable broad scientific discovery, while forestalling the unintended consequences of a disruptive technology.'||char(10)||''||char(10)||''||char(10)||'The National Science Foundation Directorates for Mathematical and Physical Sciences (MPS), Computer and Information Science and Engineering (CISE), Engineering (ENG), and Social, Behavioral and Economic Sciences (SBE) will jointly sponsor research collaborations consisting of mathematicians, statisticians, computer scientists, engineers, and social and behavioral scientists focused on the mathematical and theoretical foundations of AI. Research activities should focus on the most challenging mathematical and theoretical questions aimed at understanding the capabilities, limitations, and emerging properties of AI methods as well as the development of novel, and mathematically grounded, design and analysis principles for the current and next generation of AI approaches.'||char(10)||''||char(10)||''||char(10)||' Specific research goals include: establishing a fundamental mathematical understanding of the factors determining the capabilities and limitations of current and emerging generation s of AI systems, including, but not limited to, foundation models, generative models, deep learning, statistical learning, federated learning, and other evolving paradigms; the development of mathematically grounded design and analysis principles for the current and next generations of AI systems; rigorous approaches for characterizing and validating machine learning algorithms and their predictions; research enabling provably reliable, translational, general-purpose AI systems and algorithms; e ncouragement of new collaborations  in this interdisciplinary research community and between institution s. '||char(10)||''||char(10)||''||char(10)||'The overall goal is to establish innovative and principled design and analysis approaches for AI technology using creative yet theoretically grounded mathematical and statistical frameworks, yielding explainable and interpretable models that can enable sustainable, socially responsible, and trustworthy AI.'),
('354269', 11, 'EPSCoR Research Infrastructure Improvement Program: Focused EPSCoR Collaborations Program (FEC)', 'U.S. National Science Foundation', '24-573', 'Jan 26, 2027 12:00:00 AM EST', 'http://www.nsf.gov/publications/pub_summ.jsp?ods_key=nsf24573', 1500000, 1000000, 18000000, NULL, 'The Established Program to Stimulate Competitive Research (EPSCoR) is designed to fulfill the mandate of the National Science Foundation (NSF) to promote scientific progress nationwide. EPSCoR eligibility status is yearly updated and reported in the EPSCoR website (see EPSCoR eligibility). '||char(10)||''||char(10)||''||char(10)||'Through this program, NSF establishes partnerships with government, higher education, and industry that are designed to affect sustainable improvements in a jurisdiction''s research infrastructure, Research and Development (R&D) capacity, and hence, its R&D competitiveness.'||char(10)||''||char(10)||''||char(10)||'The FEC program (formerly known as “EPSCoR Track-2 program”) builds interjurisdictional collaborative teams of EPSCoR investigators in Science, Technology, Engineering, and Mathematics (STEM) focus areas consistent with the current National Science Foundation Strategic Plan . Projects are investigator-driven and must include researchers from at least two EPSCoR eligible jurisdictions with complementary expertise and resources necessary to address challenges, which neither party could address as well or as rapidly independently. FEC projects have a comprehensive and integrated vision to drive discovery and build sustainable STEM capacity that exemplifies institutional, geographic, and disciplinary diversity. The projects’ STEM research and education activities seek to broaden participation through the strategic inclusion and integration of all individuals, institutions, and sectors. Additionally, EPSCoR recognizes that the development of early-career faculty is critical to sustaining and advancing research capacity.'),
('355196', 19, 'NSF National Quantum Virtual Laboratory - Quantum Testbeds', 'U.S. National Science Foundation', '24-586', 'Apr 06, 2027 12:00:00 AM EDT', 'http://www.nsf.gov/publications/pub_summ.jsp?ods_key=nsf24586', NULL, NULL, 32000000, NULL, 'The National Quantum Initiative (NQI) Act 1 aims to ensure the continuing leadership of the United States (U.S.) in quantum information science and technology. In conformance with the NQI goals, an argument 2-5 was set forth for a renewed emphasis on identifying and fostering early adoption of quantum technologies to transform the field of Quantum Information Science and Engineering (QISE) and to accelerate broader impacts on society. A systematic approach to maturing quantum technology platforms by integrating end-users and potential customers from other fields of science and engineering and other sectors of the economy into cycles of research, development, and demonstration should lower the barriers for end-users to pioneer new applications. NSF support for use-inspired and translational research in QISE, combined with continued strong support of the underlying foundational research, is anticipated to accelerate development of a market for quantum technologies.'||char(10)||''||char(10)||''||char(10)||'With this program solicitation, the Foundation is taking the next step in implementing the National Quantum Virtual Laboratory (NQVL) concept as an overarching shared infrastructure designed to facilitate the translation from basic science and engineering to the resultant technology, while at the same time emphasizing and advancing its scientific and technical value. The NQVL aims to develop and utilize use-inspired and application-oriented quantum technologies. In the process, NQVL researchers will explore quantum frontiers 6 , foster the development of QISE education and workforce development strategies, engage in outreach activities at all levels, and promote input and participation from the full spectrum of talent in QISE, thereby lowering barriers at all entry points of the research enterprise. Engagement with all sectors of the United States (U.S.) QISE community will be necessary for this initiative to succeed, and, indeed, the project is designed to include participation from a full spectrum of organizations who have expertise to contribute. In particular, NSF recognizes that the involvement of industry partners is essential and will welcome these to be a part of the overall structure. Partnerships with other U.S. Federal agencies under the NQI umbrella are also encouraged.'||char(10)||''||char(10)||''||char(10)||'While this solicitation lays out the vision for the entire NQVL program that includes Quantum Science and Technology Demonstration (QSTD) projects, support for enabling technologies through Transformative Advances in Quantum Systems (TAQS), as well as a central coordination hub, only proposals for Design- and Implementation-phase QSTDs are solicited at this time.'||char(10)||''||char(10)||''||char(10)||'Submission of a QSTD:Design proposal is contingent upon the existence of a QSTD:Pilot project in the same topical area, and the positive recommendation from the Conceptual Design Review of the QSTD:Pilot project. The QSTD:Design project builds on progress made in the QSTD:Pilot phase.'||char(10)||''||char(10)||''||char(10)||'Submission of a QSTD:Implementation proposal is contingent upon the existence of a QSTD:Design project in the same topical area, and the positive recommendation from the Preliminary Design Review of the QSTD:Design project. The QSTD:Implementation project builds on progress made in the QSTD:Design phase.'||char(10)||''||char(10)||''||char(10)||'It is required that prospective PIs contact the NQVL Program Officer(s) as soon as possible, but not later than two weeks before submitting a proposal in response to this solicitation, to ascertain that the focus and budget of their proposal is appropriate for this solicitation.'||char(10)||''||char(10)||' '||char(10)||' H.R.6227 - National Quantum Initiative Act, https://www.congress.gov/bill/115th-congress/house-bill/6227 '||char(10)||' Accelerating Progress Towards Practical Quantum Advantage, A National Science Foundation Project Scoping Workshop (2022), https://arxiv.org/abs/2210.14757 '||char(10)||' Quantum Computer Systems for Scientific Discovery, PRX Quantum 2, 017001 (2021) https://doi.org/10.1103/PRXQuantum.2.017001 '||char(10)||' Development of Quantum InterConnects for Next-Generation Information Technologies, PRX Quantum 2, 017002 (2021) https://doi.org/10.1103/PRXQuantum.2.017002 '||char(10)||' Quantum Simulators: Architectures and Opportunities, PRX Quantum 2, 017003 (2021) https://doi.org/10.1103/PRXQuantum.2.017003 '||char(10)||' Quantum Frontiers: Report on Community Input to the Nation''s Strategy for Quantum Information Science, https://www.quantum.gov/wp-content/uploads/2020/10/QuantumFrontiers.pdf'),
('355439', 66, 'NIH Research Software Engineer (RSE) Award (R50 Clinical Trials Not Allowed)', 'National Institutes of Health', 'RFA-OD-24-011', 'Dec 04, 2026 12:00:00 AM EST', 'http://grants.nih.gov/grants/guide/rfa-files/RFA-OD-24-011.html', NULL, NULL, NULL, NULL, 'The purpose of this notice of funding opportunity (NOFO) is to provide salary support for exceptional Research Software Engineers (RSEs) that contribute their skills to the development and dissemination of biomedical, behavioral or health related software, tools, and algorithms as well as to the training of prospective users of these tools.'),
('356055', 31, 'Computational and Data-Enabled Science and Engineering', 'National Science Foundation', 'PD-24-8084', NULL, 'http://www.nsf.gov/funding/pgm_summ.jsp?pims_id=506212', NULL, NULL, NULL, NULL, 'Large-scale simulations and the ability to accumulate massive amounts of data have revolutionized science and engineering. The goal of the Computational and Data-enabled Science and Engineering (CDS&E) meta-program is to identify and capitalize on opportunities for major scientific and engineering breakthroughs through new computational and data-analysis approaches and best practices. The CDS&E meta-program supports projects that harness computation and data to advance knowledge and accelerate discovery above and beyond the goals of the participating individual programs. The intellectual drivers may be in an individual discipline or cut across more than one discipline in various Divisions and Directorates. A CDS&E proposal should enable and/or utilize the development and adaptation of advances in research and infrastructure in computational and data science.'||char(10)||''||char(10)||''||char(10)||'The CDS&E meta-program encourages research that pushes the envelope of science and engineering through computation and data, welcoming proposals in any research area supported by the participating divisions. A proposal may address topics that develop or enable interactions among theory, computing, experiment, and observation to achieve progress on hitherto intractable science and engineering problems. Areas of emphasis for CDS&E vary by program. PIs are advised to consult the "related programs" links below before submitting.'||char(10)||''||char(10)||''||char(10)||'The CDS&E meta-program is not intended to replace existing programs that support projects involving computation or the analysis of large or complex data sets using established methods. Rather, proposals submitted to the CDS&E meta-program must have a significant component of computational or data science that goes well beyond what would typically be included in these programs.Any proposal submitted to the CDS&E program that is not responsive to this Program Description may be transferred to or reviewed within the context of an individual program. A proposal requesting consideration within the context of CDS&E should begin the title with the identifying acronym "CDS&E:". Supplement requests to existing awards may also be considered. A CDS&E proposal should include substantive science, engineering, or computing research. Algorithm and pilot software development supporting science and engineering may also be appropriate, depending on the program. Proposers who seek to implement proven, existing methods into robust cyberinfrastructure are referred instead to the program on Cyberinfrastructure for Sustained Scientific Innovation (CSSI).'||char(10)||''||char(10)||''||char(10)||'A CDS&E proposal should be submitted to one of the "Related Programs" or Divisions by the associated submission window, deadline, or target date listed in the table below. In picking the most relevant program, PIs are advised to read program descriptions and solicitations carefully and consult with cognizant Program Officers before proposal preparation. Proposal submissions outside the receiving program''s scientific scope may be transferred to a different program or returned without review.'||char(10)||''||char(10)||''||char(10)||''||char(10)||''||char(10)||''||char(10)||'Due Dates'||char(10)||''||char(10)||' '||char(10)||' '||char(10)||' Directorate Division and Program Submission Window or Target Date '||char(10)||' '||char(10)||' '||char(10)||' '||char(10)||' '||char(10)||''||char(10)||'ENG'||char(10)||''||char(10)||' '||char(10)||' '||char(10)||''||char(10)||'Division of Chemical, Bioengineering, Environmental, and Transport Systems'||char(10)||''||char(10)||' '||char(10)||' '||char(10)||''||char(10)||' September 01, 2024 - September 16, 2024'||char(10)||''||char(10)||''||char(10)||' September 01- September 15, Annually Thereafter'||char(10)||''||char(10)||' '||char(10)||' '||char(10)||' '||char(10)||' '||char(10)||''||char(10)||'ENG'||char(10)||''||char(10)||' '||char(10)||' '||char(10)||''||char(10)||'Division of Civil, Mechanical and Manufacturing Innovation'||char(10)||''||char(10)||' '||char(10)||' '||char(10)||''||char(10)||' September 01, 2024 - September 16, 2024'||char(10)||''||char(10)||''||char(10)||' September 01- September 15, Annually Thereafter'||char(10)||''||char(10)||' '||char(10)||' '||char(10)||' '||char(10)||' '||char(10)||''||char(10)||'MPS'||char(10)||''||char(10)||' '||char(10)||' '||char(10)||''||char(10)||'Division of Chemistry - Chemical Catalysis (CAT), Chemical Mechanism, Function, and Properties (CMFP), Chemical Synthesis (SYN)'||char(10)||''||char(10)||' '||char(10)||' '||char(10)||''||char(10)||' September 01, 2024 - September 30, 2024'||char(10)||''||char(10)||''||char(10)||' September 01 - September 30, Annually Thereafter'||char(10)||''||char(10)||' '||char(10)||' '||char(10)||' '||char(10)||' '||char(10)||''||char(10)||'MPS'||char(10)||''||char(10)||' '||char(10)||' '||char(10)||''||char(10)||'Division of Materials Research'||char(10)||''||char(10)||' '||char(10)||' '||char(10)||''||char(10)||' October 15, 2024'||char(10)||''||char(10)||''||char(10)||' October 15, Annually Thereafter'||char(10)||''||char(10)||' '||char(10)||' '||char(10)||' '||char(10)||' '||char(10)||''||char(10)||'MPS'||char(10)||''||char(10)||' '||char(10)||' '||char(10)||''||char(10)||'Division of Astronomical Sciences - Advanced Technologies and Instrumentation'||char(10)||''||char(10)||' '||char(10)||' '||char(10)||''||char(10)||' October 01, 2024 - November 15, 2024'||char(10)||''||char(10)||''||char(10)||' October 01 - November 15, Annually Thereafter'||char(10)||''||char(10)||' '||char(10)||' '||char(10)||' '||char(10)||' '||char(10)||''||char(10)||'MPS'||char(10)||''||char(10)||' '||char(10)||' '||char(10)||''||char(10)||'Division of Chemistry -