('359170', 59, 'Computational Modeling and Analysis of the Impact of Genomic Variation on Function (UM1, Clinical Trial Not Allowed)', '', 'FOR-HG-25-021', NULL, '', NULL, NULL, NULL, NULL, ''),
('359252', 86, 'Advancing Research on the Application of Digital Health Technology to the Management of Type 2 Diabetes (R01- Clinical Trail Required)', 'National Institutes of Health', 'RFA-DK-26-315', 'Oct 06, 2026 12:00:00 AM EDT', 'http://grants.nih.gov/grants/guide/rfa-files/RFA-DK-26-315.html', NULL, NULL, NULL, NULL, 'This notice of funding opportunity (NOFO) invites applications designed to examine the efficacy and clinical effectiveness of multimodality digital health technology approaches to the remote management of diabetes.'),
('359499', 32, 'NSF-DFG Lead Agency Opportunity in Chemistry and Chemical Process and Transport Systems', 'U.S. National Science Foundation', '25-537', NULL, 'http://www.nsf.gov/publications/pub_summ.jsp?ods_key=nsf25537', 700000, 200000, 5000000, 10, 'Recognizing the importance of international collaborations in promoting scientific discoveries, the National Science Foundation (NSF) and the Deutsche Forschungsgemeinschaft (German Research Foundation, DFG) have signed a Memorandum of Understanding (MoU) on research cooperation. The MoU provides an overarching framework to enhance opportunities for collaborative activities between US and German research communities and sets out the principles by which jointly supported activities might be developed. To facilitate the support of collaborative work between US researchers and their German counterparts under this MoU, the Division of Chemistry (CHE) and the Division of Chemical, Bioengineering, Environmental and Transport Systems (CBET) at NSF and the Divisions of Physics and Chemistry (PC) and Engineering Sciences (ING 1) at DFG are pleased to announce a Lead Agency Opportunity for Collaborative Research in Chemistry and Chemical Process and Transport Systems.'||char(10)||''||char(10)||''||char(10)||'The goal of this Lead Agency Opportunity is to reduce barriers to working internationally by allowing US and German researchers to submit a single collaborative proposal that will undergo a single review process while funding organizations maintain budgetary control over their awards. Proposals eligible for funding consideration through this Lead Agency Opportunity should review the CHE, CBET, PC, and ING 1 program descriptions for research supported through these divisions/organizations. Proposals are expected to adhere to typical proposal budgets and durations for the relevant CHE, CBET, PC, and ING 1 programs from which funding is sought. A list of participating NSF programs can be found at: https://www.nsf.gov/od/oise/IntlCollaborations/Germany.jsp . German researchers are invited to read: www.dfg.de/nsf-che-cbet .'||char(10)||''||char(10)||''||char(10)||'Proposals submitted under this Opportunity will be reviewed by either NSF or DFG as the Lead Agency, depending on where the largest proportion of research lies. Proposals must provide a clear rationale for the need for a US-German collaboration, including the unique expertise and synergy that the collaborating groups will bring to the project. The result of the review process will be shared among the appropriate divisions (NSF/CHE and/or NSF/CBET, and DFG/PC and/or DFG/ING 1) before making final recommendations.'),
('359725', 95, 'The Metastasis Research Network (MetNet): MetNet Research Projects (U01 Clinical Trial Not Allowed)', 'National Institutes of Health', 'PAR-26-134', 'Nov 22, 2028 12:00:00 AM EST', '', 500000, NULL, NULL, NULL, 'The National Cancer Institute''s (NCI) Metastasis Research Network (MetNet) is a collection of U54 Research Centers that support using systems-level approaches to understand pressing questions in metastasis. The overall goal of the MetNet is to advance our understanding of metastasis as a whole body, systems-level problem to develop a comprehensive and cohesive picture of the processes involved. Through this Notice of Funding Opportunity (NOFO), the NCI invites applications for MetNet Research Projects. These Research Projects should be defined as discrete entities that use systems-level approaches to address gaps and opportunities in metastasis research to integrate into the MetNet and complement ongoing research across the Network.'),
('359864', 57, 'Forecast to Publish a Funding Opportunity Announcement for EmbraceHealth Clinical Research Network to Reduce Health Disparities &ndash; Coordinating Center', '', 'FOR-MD-25-009', NULL, '', NULL, NULL, NULL, NULL, ''),
('359865', 58, 'Notice of Intent to Publish a Forecast for EmbraceHealth Clinical Research Network to Reduce Health Disparities &ndash; Research Sites', '', 'FOR-MD-25-008', NULL, '', NULL, NULL, NULL, NULL, ''),
('359949', 98, 'Novel Experiential Technologies Assisting Individual Learning (NExT AI) Hubs (P20 Clinical Trial Optional)', 'National Institutes of Health', 'RFA-HD-27-006', 'Oct 02, 2026 12:00:00 AM EDT', '', NULL, NULL, 1600000, 3, 'This Notice of Funding Opportunity (NOFO) invites exploratory grant applications, hereafter referred to as the Novel Experiential Technologies Assisting Individual learning Hubs or NExT AI Hubs (formerly Learning Disabilities Innovation Hubs), to address the impact of Artificial Intelligence (AI) technologies on developmental outcomes in children diagnosed with or at risk for developing a specific learning disability (SLD) impacting reading, writing, and mathematics. NExT AI Hubs include a single Research Project and a Leadership Core that support the goals and aims of the Hub. This NOFO seeks to serve as a catalyst to 1) speed the maturation of nascent/novel, high-impact, high-risk research that advances understanding of the role AI technology plays in supporting, improving, or limiting the learning, cognitive, and socio-emotional needs of children at risk for or diagnosed with SLDs, 2) build an evidence base for the SLD community to inform policy or practice, and 3) provide project-embedded, career-enhancing research and professional development opportunities to support the next generation of transdisciplinary SLD scientists. This initiative provides opportunities to support planning and building a body of research and corresponding intellectual infrastructure to enable NExT AI investigators to compete for large research and program project opportunities in the future.This NOFO aims to integrate research topics that are of relevance to various research programs at the Eunice Kennedy Shriver National Institute of Child Health and Human Development (NICHD) and align with the NICHD Strategic Plan. The NOFO intends to build cross-programmatic, transdisciplinary and cross-cutting scientific research, and critically nurture the development of early career investigators capable of conducting this research.'),
('359966', 21, 'National Science Foundation Translation to Practice', 'U.S. National Science Foundation', '25-540', 'Nov 17, 2026 12:00:00 AM EST', 'http://www.nsf.gov/publications/pub_summ.jsp?ods_key=nsf25540', 2000000, 600000, 30000000, NULL, 'The U.S. NSF Directorate for Technology, Innovation and Partnerships (NSF TIP) partners across sectors to advance three primary focus areas – accelerating technology translation and development, fostering regional innovation and economic growth, and preparing the American workforce for future high-wage jobs in STEM fields.'||char(10)||''||char(10)||''||char(10)||'The translation of research to practice ensures that the insights and innovations developed through scientific study and experimentation have tangible, positive impacts for the Nation. These impacts include improving the quality of life, promoting economic and job growth, ensuring national security, and maintaining global competitiveness. Indeed, scientific and engineering breakthroughs have the potential to address critical societal challenges in industries such as aerospace, agriculture, communications, education, energy, healthcare, national security, and transportation – but the translation of discoveries and innovations from the laboratory to society often takes many forms including non-linear pathways.'||char(10)||''||char(10)||''||char(10)||'The NSF TTP program was developed with several goals in mind:'||char(10)||''||char(10)||' '||char(10)||' To identify and support use-inspired research and translational activities enabling a continuum from foundational research to practice; '||char(10)||' To develop partnerships and collaborations between institutions of higher education and other entities (e.g., industry, state/local/national government agencies, philanthropies, open-source ecosystems, for-benefit, for-profit and non-profit organizations, international organizations, etc.); '||char(10)||' To promote and advance the education and training of students and postdoctoral researchers, encouraging the participation of all Americans in STEM including innovation and entrepreneurship; and '||char(10)||' To identify future customer needs and opportunities and bring these to the forefront in the conduct of use-inspired research and translational activities. '||char(10)||' '||char(10)||''||char(10)||'The NSF TTP program offers three tracks that represent different starting points or stages in moving discoveries and innovations from the laboratory to practice:'||char(10)||''||char(10)||' '||char(10)||' NSF TTP-Explore (NSF TTP-E) is a pilot track that is likely to be the first step for researchers seeking to translate their basic research to practice. To be eligible for the NSF TTP-E track, proposers must have an active, eligible, NSF research award (see Eligibility Information for further details). TTP-E is designed to encourage current, eligible NSF awardees to intentionally pursue applications of their research with the potential for societal impact. The NSF TTP-E track provides the opportunity to obtain an extension of the initial award period of a current NSF award for up to two years in order to offer investigators an opportunity to explore adventurous, high-risk, use-inspired research and initial translational activities as the starting point for translation that was not covered by the original research award. '||char(10)||' NSF TTP-Translate (NSF TTP-T) starts with use-inspired research and initial translational activities and further matures the idea(s), iterates and improves the solution(s), and lowers the barrier(s) to effective translation of research from lab to practice. '||char(10)||' NSF TTP-Partner (NSF TTP-P) supports translational efforts that demand one or more partnerships for technology development and deployment. Here, strategic partnerships with stakeholders beyond U.S. institutions of higher education are essential ingredients for success and may include industry partners, government entities at all levels, philanthropies, international organizations, or other groups associated with large scale productization and distribution. The NSF TTP-P track requires an NSF-Catalyzed Partnership with an organization that will assist in the translation to practice. In addition to the Principal Investigator (PI), NSF TTP-P proposals must include a co-PI or Senior/Key Personnel who is a member or employee of the NSF-Catalyzed Partner. Partnerships with U.S. institutions of higher education are valued, but NSF TTP strongly prioritizes NSF-Catalyzed Partnerships that are able to help bring the product, process, or service to the market, potentially through licensing agreements, startup or small business formation, incorporation into an existing open-source ecosystem, development into standards setting arrangements, etc.'),
('360149', 7, 'Computer and Information Science and Engineering (CISE): Future Computing Research', 'U.S. National Science Foundation', '25-543', 'Sep 10, 2026 12:00:00 AM EDT', 'http://www.nsf.gov/publications/pub_summ.jsp?ods_key=nsf25543', 12000000, 600000, 280000000, 600, 'The NSF CISE Directorate supports research and education projects that develop new knowledge in all aspects of computing, communications, and information science and engineering through the following Future Computing Research (Future CoRe) programs:'||char(10)||''||char(10)||' '||char(10)||' Algorithmic Foundations (AF) program; '||char(10)||' Communications and Information Foundations (CIF) program; '||char(10)||' Computer Systems Research (CSR) program; '||char(10)||' Computing Education Research (CER) program; '||char(10)||' Cyber-Physical System Foundations and Connected Communities (CPS) program; '||char(10)||' Foundations of Emerging Technologies (FET) program; '||char(10)||' Human-Centered Computing (HCC) program; '||char(10)||' Information Integration and Informatics (III) program; '||char(10)||' Networking Technology and Systems (NeTS) program; '||char(10)||' Robust Intelligence (RI) program;and '||char(10)||' Software and Hardware Foundations (SHF) program; '||char(10)||' '||char(10)||' The CISE Future Computing Research program anticipates a portfolio of awards with a range of budgets and durations, including projects of smaller scope. Project durations and budgets must be commensurate with the scope of the proposed work up to the maximum limit of $1,000,000 with a duration up to 4 years. Typical projects are approximately $150,000 to $250,000 per year and are 3 to 4 years in duration. Projects are discouraged from exceeding $300,000 in any single year. Estimated program budget, number of awards, and average award size/duration are subject to the availability of funds.'),
